<script>
  export let data;
  const { copy, events } = data;
  const release = copy.releases;
  const money = (amount, currency) => new Intl.NumberFormat('en-KE', { style: 'currency', currency: currency || 'KES', maximumFractionDigits: 0 }).format(Number(amount || 0));
  const event = (kind) => ({ created: 'Created by issuer', acquired: 'First acquired', transferred: 'Transferred', verified: 'Authenticity verified', listing_opened: 'Offered for resale', offer_accepted: 'Offer accepted' }[kind] || String(kind).replaceAll('_', ' '));
  const serial = release?.edition_size ? `${String(copy.edition_number ?? 1).padStart(2, '0')}/${release.edition_size}` : 'Open Edition';
</script>
<svelte:head><title>{release?.title || 'Authenticated copy'} — Noizes</title></svelte:head>
<main><a class="back" href="/exchange/collector-market">← Collector Market</a><div class="heading"><div><p class="eyebrow">Authenticated copy</p><p class="artist">{release?.artist_name}</p><h1>{release?.title} <span>— {serial}</span></h1></div><p class="status">◈ Verified against Noizes Registry</p></div><section class="hero">{#if copy.cover_url}<img src={copy.cover_url} alt={`${release?.title} artwork`} />{:else}<div class="art">NZ</div>{/if}<div class="summary"><p class="chip">▣ {release?.edition_name || release?.edition_type} · Copy {serial}</p><h2>Authenticated edition identity</h2><p>Files can be copied. This transaction transfers the authenticated edition identity and its recorded provenance.</p><dl><div><dt>Issuer</dt><dd>{release?.artist_name}</dd></div><div><dt>Issued</dt><dd>{new Date(copy.acquired_at).toLocaleDateString('en-KE', { dateStyle: 'long' })}</dd></div><div><dt>Registry status</dt><dd>Signature valid · verification recorded</dd></div><div><dt>Public custodian</dt><dd>Verified collector</dd></div></dl></div></section><div class="columns"><section class="timeline"><p class="eyebrow">Provenance history</p><h2>Public record</h2>{#each events as entry}<div class="event"><span>↗</span><div><h3>{event(entry.kind)}</h3><p>Registry-attested event</p></div><time>{new Date(entry.occurred_at).toLocaleDateString('en-KE', { month: 'short', day: 'numeric', year: 'numeric' })}</time></div>{/each}{#if !events.length}<p class="muted">No public event records were found for this copy yet.</p>{/if}</section><aside><p class="eyebrow">Collector Market</p><h2>{copy.accepting_offers ? 'Offers open' : 'Not listed'}</h2><p class="price">{money(copy.price_paid, copy.currency)}</p><p class="split">Seller 85% · Artist 10% · Noizes 5%</p>{#if copy.accepting_offers}<a class="buy" href="/exchange">Make offer →</a>{/if}<p class="fine">This record verifies edition identity and provenance. Package files remain portable and independently usable.</p></aside></div></main>
