-size:.82rem}.buy{display:block;background:#6d3df2;color:#fff;padding:13px;text-align:center;border-radius:9px;text-decoration:none;font-weight:800;margin:20px 0}.fine{border-top:1px solid #342f41;padding-top:15px;color:#aaa2b9;font-size:.8rem;line-height:1.45}@media(max-width:720px){.heading,.hero,.columns{grid-template-columns:1fr;display:grid}.heading{align-items:start}.hero>img,.art{min-height:260px;height:260px}.summary{padding:23px}.columns{gap:12px}.event{grid-template-columns:30px 1fr}.event time{grid-column:2}.timeline,aside{padding:19px}}</style>
